SELECT MIN(GSserved) AS lowest_grade
FROM schools
WHERE NCESDist = '0632640';

SELECT COUNT(DISTINCT name) AS num_release_promo_cards
FROM cards
WHERE promoTypes LIKE '%release%';

SELECT COUNT(*) AS fireball_rulings_count
FROM rulings
WHERE text LIKE '%Fireball%';

SELECT COUNT(DISTINCT language) AS num_languages
FROM foreign_data
WHERE name = 'Swamp';

