SELECT ROUND(AVG(weight), 1) AS avg_weight_green_skin_kg
FROM superhero
WHERE colour = 'Green' AND weight IS NOT NULL;

SELECT COUNT(*) AS non_good_bad_heroes
FROM superhero
WHERE alignment NOT IN ('good', 'bad');

